{{!-- Styling parameters: class, titleClass, gridClass, cardClass, contentClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Component: Featured Posts | Usage: {{> "components/featured-posts"}} --}}
{{#get "posts" filter="featured:true" limit="3" include="authors,tags"}}
{{#if posts}}
<section class="ghcn-featured{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}} ghcn-container" aria-label="Featured posts">
    <div class="ghcn-featured__heading">
        <div><span class="ghcn-badge">Featured</span><h2 class="ghcn-featured__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">Editor’s picks</h2></div>
        <a href="{{@site.url}}">View all posts <span aria-hidden="true">&rarr;</span></a>
    </div>
    <div class="ghcn-featured__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">
        {{#foreach posts}}
        <article class="ghcn-featured__card{{#if ghostcnStyles.cardClass}} {{ghostcnStyles.cardClass}}{{/if}}{{#has index="0"}} ghcn-featured__card--lead{{/has}}">
            {{#if feature_image}}
                <a class="ghcn-featured__image" href="{{url}}" tabindex="-1" aria-hidden="true">
                    <img src="{{img_url feature_image size="l"}}" alt="" loading="{{#has index="0"}}eager{{else}}lazy{{/has}}" />
                </a>
            {{/if}}
            <div class="ghcn-featured__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
                <div class="ghcn-featured__meta">{{#if primary_tag}}<a href="{{primary_tag.url}}">{{primary_tag.name}}</a><span aria-hidden="true">&bull;</span>{{/if}}<span>{{reading_time}}</span></div>
                <h3><a href="{{url}}">{{title}}</a></h3>
                {{#has index="0"}}{{#if excerpt}}<p>{{excerpt words="30"}}</p>{{/if}}{{/has}}
            </div>
        </article>
        {{/foreach}}
    </div>
</section>
{{/if}}
{{/get}}
{{/with}}

/* ghostcn: Featured Posts */
.ghcn-featured { box-sizing: border-box; min-width: 0; margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px)); font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); }
.ghcn-featured *, .ghcn-featured *::before, .ghcn-featured *::after { box-sizing: border-box; }
.ghcn-featured__heading { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px; margin-bottom: var(--ghcn-section-gap, 20px); }
.ghcn-featured__title { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 8px 0 0; }
.ghcn-featured__heading > a { color: var(--muted-foreground); font-size: var(--ghcn-text-small, 14px); font-weight: 600; text-decoration: none; }
.ghcn-featured__grid { display: grid; grid-template-columns: minmax(0,2fr) minmax(0,1fr); gap: var(--ghcn-grid-gap, 16px); }
.ghcn-featured__card { box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b); display: flex; flex-direction: column; overflow: hidden; transition: border-color 180ms ease; }
.ghcn-featured__card:hover { border-color: color-mix(in srgb, var(--foreground) 22%, var(--border)); }
.ghcn-featured__card--lead { grid-row: span 2; }
.ghcn-featured__card:only-child { grid-column: 1 / -1; grid-row: auto; }
.ghcn-featured__image { display: block; aspect-ratio: 16 / 9; overflow: hidden; background: var(--muted); }
.ghcn-featured__image img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform 300ms ease; }
.ghcn-featured__card:hover .ghcn-featured__image img { transform: scale(1.02); }
@media (prefers-reduced-motion: reduce) { .ghcn-featured__card, .ghcn-featured__image img { transition: none; transform: none; } }
.ghcn-featured__card--lead:not(:only-child) .ghcn-featured__image { flex: 1 1 auto; }
.ghcn-featured__content { padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px)); }
.ghcn-featured__meta { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; color: var(--muted-foreground); font-size: var(--ghcn-text-meta, 13px); }
.ghcn-featured__meta a, .ghcn-featured__content h3 a { color: inherit; text-decoration: none; }
.ghcn-featured a:hover { text-decoration: underline; text-underline-offset: 3px; }
.ghcn-featured__content h3 { font-size: var(--ghcn-title-card, 20px); font-weight: 650; line-height: 1.3; letter-spacing: -.025em; color: inherit; margin: 0; }
.ghcn-featured__card--lead h3 { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; }
.ghcn-featured__content p { max-width: 60ch; margin: 8px 0 0; color: var(--muted-foreground); font-size: var(--ghcn-text-small, 14px); }
.ghcn-featured:focus-visible, :where(.ghcn-featured) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
.ghcn-featured__image:focus-visible { outline-offset: -3px; }
@media (max-width: 720px) { .ghcn-featured__grid { grid-template-columns: 1fr; } .ghcn-featured__card--lead { grid-row: auto; } }
